use context_api::{
    commands::{
        Command,
        CommandResult,
    },
    types::TraceSummary,
};
use rmcp::schemars::{
    self,
    JsonSchema,
};
use serde::{
    Deserialize,
    Serialize,
};

/// Input schema for the `execute` tool.
///
/// The `command` field is the full `Command` enum — its JSON schema is
/// auto-generated by schemars and documents every command variant and its
/// fields for the MCP client.
///
/// Because of `#[serde(flatten)]` the input JSON **is** the command itself
/// (no extra wrapping layer). For example:
///
/// ```json
/// {"command": "create_workspace", "name": "demo"}
/// ```
#[derive(Debug, Deserialize, JsonSchema)]
pub(crate) struct ExecuteInput {
    /// The command to execute. See the schema for all available commands.
    ///
    /// Examples:
    /// - `{"command": "create_workspace", "name": "my-graph"}`
    /// - `{"command": "add_atoms", "workspace": "my-graph", "chars": ["a","b","c"]}`
    /// - `{"command": "insert_sequence", "workspace": "my-graph", "text": "hello"}`
    /// - `{"command": "search_sequence", "workspace": "my-graph", "text": "hel"}`
    /// - `{"command": "read_as_text", "workspace": "my-graph", "index": 3}`
    /// - `{"command": "save_workspace", "name": "my-graph"}`
    #[serde(flatten)]
    pub(crate) command: Command,

    /// Enable tracing for this command execution.
    /// When true, engine internal events (search transitions,
    /// insert split/join phases, etc.) are captured to a log file.
    /// The response will include a `trace` field with the log filename
    /// and event count.
    #[serde(default)]
    pub(crate) trace: bool,
}

/// Output wrapper for the `execute` tool.
///
/// API-level errors are returned as `success: false` with an `error` message
/// (not as MCP-level errors) so the agent can read and react to them.
#[derive(Debug, Serialize, Deserialize)]
pub(crate) struct ExecuteOutput {
    /// Whether the command succeeded.
    pub(crate) success: bool,
    /// The result (present when `success` is `true`).
    #[serde(skip_serializing_if = "Option::is_none")]
    pub(crate) result: Option<CommandResult>,
    /// Error message (present when `success` is `false`).
    #[serde(skip_serializing_if = "Option::is_none")]
    pub(crate) error: Option<String>,
    /// Trace summary (present when trace: true was requested and a workspace-scoped command was run).
    #[serde(skip_serializing_if = "Option::is_none")]
    pub(crate) trace: Option<TraceSummary>,
}

/// Input schema for the `help` tool.
#[derive(Debug, Deserialize, JsonSchema)]
pub(crate) struct HelpInput {
    /// Optional: a specific command name to get detailed help for.
    /// If omitted, returns an overview of all commands grouped by category.
    ///
    /// Examples: "create_workspace", "insert_sequence", "search_sequence"
    #[serde(default)]
    pub(crate) command: Option<String>,

    /// Optional: a category name to list only that category's commands.
    /// If omitted (and no specific command requested), returns all categories.
    ///
    /// Valid categories: "workspace", "atoms", "patterns", "search", "insert", "read", "debug"
    #[serde(default)]
    pub(crate) category: Option<String>,
}

/// Input schema for the `workflow` tool.
#[derive(Debug, Deserialize, JsonSchema)]
pub(crate) struct WorkflowInput {
    /// The workflow template to retrieve.
    /// Use "list" (or omit) to see all available workflows.
    ///
    /// Available workflows:
    /// - "list" — List all available workflow templates
    /// - "basic" — Create workspace, add atoms, insert, search, read, save
    /// - "bulk_insert" — Insert multiple sequences efficiently
    /// - "search_and_read" — Search for patterns and read results
    /// - "inspect" — Debug and inspect graph state
    /// - "persistence" — Save, close, reopen workflow
    /// - "trace_and_debug" — Execute with tracing, then analyze the trace log
    #[serde(default = "default_workflow_name")]
    pub(crate) name: String,

    /// Workspace name to substitute into the template commands.
    /// Defaults to "demo" if not provided.
    #[serde(default = "default_workspace_name")]
    pub(crate) workspace: String,
}

fn default_workflow_name() -> String {
    "list".to_string()
}

fn default_workspace_name() -> String {
    "demo".to_string()
}

/// A single command's help information.
#[derive(Debug, Serialize)]
pub(crate) struct CommandHelp {
    pub(crate) name: &'static str,
    pub(crate) category: &'static str,
    pub(crate) summary: &'static str,
    pub(crate) parameters: &'static [ParamHelp],
    pub(crate) example: &'static str,
    pub(crate) result_type: &'static str,
    pub(crate) notes: &'static str,
}

/// A parameter description for a command.
#[derive(Debug, Serialize)]
pub(crate) struct ParamHelp {
    pub(crate) name: &'static str,
    #[serde(rename = "type")]
    pub(crate) param_type: &'static str,
    pub(crate) required: bool,
    pub(crate) description: &'static str,
}

/// Category metadata for the overview.
pub(crate) struct CategoryInfo {
    pub(crate) name: &'static str,
    pub(crate) display: &'static str,
    pub(crate) description: &'static str,
}

/// A single step in a workflow template.
#[derive(Debug, Serialize)]
pub(crate) struct WorkflowStep {
    pub(crate) step: usize,
    pub(crate) description: &'static str,
    pub(crate) command: serde_json::Value,
}

/// A complete workflow template.
#[derive(Debug, Serialize)]
pub(crate) struct WorkflowTemplate {
    pub(crate) name: &'static str,
    pub(crate) title: &'static str,
    pub(crate) description: &'static str,
    pub(crate) steps: Vec<WorkflowStep>,
    pub(crate) tips: Vec<&'static str>,
}

/// Summary of an available workflow.
#[derive(Debug, Serialize)]
pub(crate) struct WorkflowSummary {
    pub(crate) name: &'static str,
    pub(crate) title: &'static str,
    pub(crate) description: &'static str,
}

/// Extract the workspace name from a command, if it has one.
pub(crate) fn extract_workspace_name(cmd: &Command) -> Option<&str> {
    match cmd {
        Command::CreateWorkspace { name }
        | Command::CreateWorkspaceFromNgrams { name, .. }
        | Command::OpenWorkspace { name }
        | Command::CloseWorkspace { name }
        | Command::SaveWorkspace { name }
        | Command::DeleteWorkspace { name }
        | Command::ImportWorkspace { name, .. } => Some(name.as_str()),
        Command::ListWorkspaces => None,
        Command::AddAtom { workspace, .. }
        | Command::AddAtoms { workspace, .. }
        | Command::GetAtom { workspace, .. }
        | Command::ListAtoms { workspace }
        | Command::AddSimplePattern { workspace, .. }
        | Command::GetVertex { workspace, .. }
        | Command::ListVertices { workspace }
        | Command::SearchPattern { workspace, .. }
        | Command::SearchSequence { workspace, .. }
        | Command::InsertFirstMatch { workspace, .. }
        | Command::InsertSequence { workspace, .. }
        | Command::InsertSequences { workspace, .. }
        | Command::ReadPattern { workspace, .. }
        | Command::ReadAsText { workspace, .. }
        | Command::ReadSequence { workspace, .. }
        | Command::ReadFile { workspace, .. }
        | Command::GetSnapshot { workspace }
        | Command::GetStatistics { workspace }
        | Command::ValidateGraph { workspace }
        | Command::ShowGraph { workspace }
        | Command::ShowVertex { workspace, .. }
        | Command::ListLogs { workspace, .. }
        | Command::GetLog { workspace, .. }
        | Command::QueryLog { workspace, .. }
        | Command::AnalyzeLog { workspace, .. }
        | Command::SearchLogs { workspace, .. }
        | Command::DeleteLog { workspace, .. }
        | Command::DeleteLogs { workspace, .. }
        | Command::ExportWorkspace { workspace, .. }
        | Command::RenderAsciiGraph { workspace, .. }
        | Command::CompareWorkspaces {
            workspace_a: workspace,
            ..
        }
        | Command::CompareVertices {
            workspace_a: workspace,
            ..
        } => Some(workspace.as_str()),
    }
}